  const rolePanelsEnabled = params.rolePanelsEnabled === true;
  const testActorsEnabled = params.testActorsEnabled === true;
  const isAdmin = params.isAdmin === true;
  const activePerspective = params.activePerspective
    ?? (isSpecialist ? "quality_management" : planningMode ? "manager" : "aftersales");
